input.command:
cat > /private/tmp/claude-501/-Users-akima-workspace-claude-plugins/66eda52f-7cc8-4a09-8e6c-29bd7c64bdd0/scratchpad/bold.py <<'EOF'
import subprocess, sys
from markdown_it import MarkdownIt
md = MarkdownIt("commonmark").enable("table")
repo = "/Users/akima/workspace/claude-plugins"
files = subprocess.run(["git","-C",repo,"diff","--name-only","6cfa59b2..bc4b1b5f","--","*.md"],capture_output=True,text=True).stdout.split()
def leftovers(rev, f):
    src = subprocess.run(["git","-C",repo,"show",f"{rev}:{f}"],capture_output=True,text=True).stdout
    out = []
    for tok in md.parse(src):
        if tok.type == "inline":
            for ch in tok.children or []:
                if ch.type == "text" and "**" in ch.content:
                    out.append((tok.map[0]+1 if tok.map else 0, ch.content))
    return out
for f in files:
    b = leftovers("6cfa59b2", f); h = leftovers("bc4b1b5f", f)
    bset = {c for _, c in b}
    for ln, c in h:
        if c not in bset:
            print(f"{f}:{ln}: {c[:160]!r}")
    print(f"# {f}: base={len(b)} head={len(h)}", file=sys.stderr)
EOF
